def solve(n):
    if n < 2:
        return 0
    MAXN = 10**6
    sieve = bytearray(b'\x01') * MAXN
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, math.isqrt(MAXN - 1) + 1):
        if sieve[i]:
            sieve[i * i:MAXN:i] = b'\x00' * len(sieve[i * i:MAXN:i])
    primes = [i for i in range(MAXN) if sieve[i]]
    pi_small = [0] * MAXN
