        if sieve[i]:
            c += 1
        pi_small[i] = c

    @lru_cache(maxsize=None)
    def phi(x, a):
        if a == 0:
            return x
        if a == 1:
            return x - x // 2
        if a == 2:
            return x - x // 2 - x // 3 + x // 6
        return phi(x, a - 1) - phi(x // primes[a - 1], a - 1)

    def pi(x):
        if x < MAXN:
            return pi_small[x]
        a = pi(math.floor(x ** (1/3)) + 2)  # pi(cbrt(x))
        b = pi(math.isqrt(x))
        s = phi(x, a) + (b + a - 2) * (b - a + 1) // 2
        for i in range(a, b):
            s -= pi(x // primes[i])
            if i + 1 < b:
                s -= b - i - 1
        return s

    return pi(n)
