def solve(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not all('0' <= c <= '9' for c in p):
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if not (0 <= int(p) <= 255):
            return False
    return True

